window.TL={"beats": {"b01": {"id": "b01", "text": "Hi, I'm Juno. Here's AIA Voice Insights, in two minutes.", "t0": 0.6, "t1": 5.17}, "b02": {"id": "b02", "text": "The conversation is the easy part. Then come notes, fact-finds and follow-ups, typed from memory, late and uneven. Risks surface weeks later.", "t0": 5.45, "t1": 15.26}, "b03": {"id": "b03", "text": "Capture it your way: dictate after the meeting, listen live, or let me debrief you, in English, Mandarin, Malay or Tamil. No re-typing, and every customer served in their language.", "t0": 15.54, "t1": 27.81}, "b04": {"id": "b04", "text": "In a debrief, I say what I understood and ask up to five short questions about gaps. A live meter tracks twenty-six fact-find fields, and risky promises are flagged.", "t0": 28.09, "t1": 37.15}, "b05": {"id": "b05", "text": "With the customer, I follow needs, mood and buying signals, suggest the next best question, and flag risky statements as they're said.", "t0": 37.43, "t1": 45.3}, "b06": {"id": "b06", "text": "Eleven specialist agents then analyse the case in thirty to forty seconds, grounded in product documents. Only a person can start the analysis, and every result is a suggestion.", "t0": 45.58, "t1": 56.17}, "b07": {"id": "b07", "text": "The advice pack is drafted for you: fact-find, record of advice, follow-up, CRM note and report. You edit and sign off. Nothing is sent without you.", "t0": 56.45, "t1": 66.48}, "b08": {"id": "b08", "text": "Ask me why a product was picked, or what if there's one more child. The sums are done by code, not by the AI, and the working is shown.", "t0": 66.76, "t1": 74.09}, "b09": {"id": "b09", "text": "Say Hey Juno to go hands-free: open screens, press buttons, hear a briefing or the full report, and say stop any time.", "t0": 74.37, "t1": 82.84}, "b10": {"id": "b10", "text": "Before the next meeting, rehearse. I play your customer from your own debrief, then coach what landed and what you missed.", "t0": 83.12, "t1": 90.1}, "b11": {"id": "b11", "text": "It's built for trust: ID and card numbers are never stored, weak speech is filtered out, and Juno suggests while you decide.", "t0": 90.38, "t1": 98.33}, "b12": {"id": "b12", "text": "The impact: advisors get time back to sell, customers get faster follow-up, compliance is caught early, and leaders see one view across the agency force.", "t0": 98.61, "t1": 107.44}, "b13": {"id": "b13", "text": "Premiums are up thirty-six percent, yet seventy-four percent of critical illness cover is missing. Six hours back per rep is about seventy-four thousand hours a month, an illustration.", "t0": 107.72, "t1": 118.65}, "b14": {"id": "b14", "text": "Let's prove it together. Just say, Hey Juno.", "t0": 118.93, "t1": 122.99}}, "slides": [{"id": "s01", "start": 0, "beat": "b01"}, {"id": "s02", "start": 5.1, "beat": "b02"}, {"id": "s03", "start": 15.19, "beat": "b03"}, {"id": "s04", "start": 27.74, "beat": "b04"}, {"id": "s05", "start": 37.08, "beat": "b05"}, {"id": "s06", "start": 45.23, "beat": "b06"}, {"id": "s07", "start": 56.1, "beat": "b07"}, {"id": "s08", "start": 66.41, "beat": "b08"}, {"id": "s09", "start": 74.02, "beat": "b09"}, {"id": "s10", "start": 82.77, "beat": "b10"}, {"id": "s11", "start": 90.03, "beat": "b11"}, {"id": "s12", "start": 98.26, "beat": "b12"}, {"id": "s13", "start": 107.37, "beat": "b13"}, {"id": "s14", "start": 118.58, "beat": "b14"}], "total": 123.99};
window.DECK={"title": "AIA Voice Insights: product overview", "beats": {"b01": "Hi, I'm Juno. Here's AIA Voice Insights, in two minutes.", "b02": "The conversation is the easy part. Then come notes, fact-finds and follow-ups, typed from memory, late and uneven. Risks surface weeks later.", "b03": "Capture it your way: dictate after the meeting, listen live, or let me debrief you, in English, Mandarin, Malay or Tamil. No re-typing, and every customer served in their language.", "b04": "In a debrief, I say what I understood and ask up to five short questions about gaps. A live meter tracks twenty-six fact-find fields, and risky promises are flagged.", "b05": "With the customer, I follow needs, mood and buying signals, suggest the next best question, and flag risky statements as they're said.", "b06": "Eleven specialist agents then analyse the case in thirty to forty seconds, grounded in product documents. Only a person can start the analysis, and every result is a suggestion.", "b07": "The advice pack is drafted for you: fact-find, record of advice, follow-up, CRM note and report. You edit and sign off. Nothing is sent without you.", "b08": "Ask me why a product was picked, or what if there's one more child. The sums are done by code, not by the AI, and the working is shown.", "b09": "Say Hey Juno to go hands-free: open screens, press buttons, hear a briefing or the full report, and say stop any time.", "b10": "Before the next meeting, rehearse. I play your customer from your own debrief, then coach what landed and what you missed.", "b11": "It's built for trust: ID and card numbers are never stored, weak speech is filtered out, and Juno suggests while you decide.", "b12": "The impact: advisors get time back to sell, customers get faster follow-up, compliance is caught early, and leaders see one view across the agency force.", "b13": "Premiums are up thirty-six percent, yet seventy-four percent of critical illness cover is missing. Six hours back per rep is about seventy-four thousand hours a month, an illustration.", "b14": "Let's prove it together. Just say, Hey Juno."}, "slides": [{"id": "s01", "kind": "title", "beat": "b01", "kicker": "MEET JUNO", "title": "Every conversation, <em>understood.</em>", "sub": "AIA Voice Insights: listen, understand, draft, advise. The advisor stays in charge."}, {"id": "s02", "kind": "problem", "beat": "b02", "kicker": "THE PROBLEM", "title": "Great advice gets lost in <em>admin</em>", "rows": [{"icon": "clock", "title": "Hours lost after every meeting", "sub": "Notes, fact-finds and records typed by hand"}, {"icon": "message", "title": "Slow, uneven follow-up", "sub": "Customers wait, and language needs are served unevenly"}, {"icon": "alert", "title": "Risk found late", "sub": "A risky promise surfaces in a file review, weeks on"}, {"icon": "chart", "title": "No view for leaders", "sub": "No live picture of volume, quality or needs"}], "impact": {"label": "THE COST", "big": "Time, trust and risk", "text": "Admin crowds out selling, and quality depends on one person's memory."}}, {"id": "s03", "kind": "feature", "beat": "b03", "kicker": "CAPTURE", "title": "Three ways to <em>capture</em> a conversation", "rows": [{"icon": "mic", "title": "After the meeting", "sub": "Dictate a summary; it is structured and checked for gaps"}, {"icon": "users", "title": "With the customer", "sub": "Live listening, mood, needs and the next best question"}, {"icon": "sparkle", "title": "Debrief with Juno", "sub": "Dictate, then Juno checks the gaps and reads back"}, {"icon": "globe", "title": "Four languages", "sub": "English, Mandarin, Malay, Tamil, and mixed speech"}], "impact": {"label": "BUSINESS IMPACT", "big": "No re-typing", "text": "Agents capture once, and every customer is served in the language they prefer."}}, {"id": "s04", "kind": "feature", "beat": "b04", "kicker": "DEBRIEF WITH JUNO", "title": "Nothing is lost <em>before</em> the analysis", "rows": [{"icon": "mic", "title": "Dictate freely", "sub": "Juno listens and never interrupts a pause"}, {"icon": "search", "title": "Up to five short questions", "sub": "Only about what is missing or unclear"}, {"icon": "gauge", "title": "Live fact-find meter", "sub": "26 fields counted as the advisor answers"}, {"icon": "alert", "title": "Compliance catch", "sub": "A promise or guarantee is raised before it is filed"}], "impact": {"label": "BUSINESS IMPACT", "big": "Fewer missed needs", "text": "A more complete fact-find, and safer advice, from the first debrief."}}, {"id": "s05", "kind": "feature", "beat": "b05", "kicker": "LIVE WITH THE CUSTOMER", "title": "A coach in the <em>conversation</em>", "rows": [{"icon": "heart", "title": "Needs, mood and buying signals", "sub": "A live picture of the customer as they speak"}, {"icon": "users", "title": "Family map", "sub": "Dependants, goals and concerns, in the customer's words"}, {"icon": "target", "title": "Next best question", "sub": "Suggested while the meeting is still going"}, {"icon": "alert", "title": "Risky statements flagged", "sub": "Caught as they are said, not weeks later"}], "impact": {"label": "BUSINESS IMPACT", "big": "Better conversations", "text": "Stronger discovery and compliance caught in the moment."}}, {"id": "s06", "kind": "feature", "beat": "b06", "kicker": "THE AGENT TEAM", "title": "Eleven agents, one <em>grounded</em> suggestion", "rows": [{"icon": "bolt", "title": "30 to 40 seconds", "sub": "From conversation to a full suggestion"}, {"icon": "book", "title": "Grounded in product documents", "sub": "Reasons, concerns and citations you can check"}, {"icon": "shield", "title": "Compliance check built in", "sub": "Every proposal is screened before it is shown"}, {"icon": "check", "title": "A person starts it", "sub": "Only the advisor's own click starts the analysis"}], "impact": {"label": "BUSINESS IMPACT", "big": "Consistent, explainable", "text": "The same quality of suggestion for every advisor, in seconds."}}, {"id": "s07", "kind": "feature", "beat": "b07", "kicker": "ADVICE PACK", "title": "The paperwork is <em>drafted</em> for you", "rows": [{"icon": "file", "title": "Fact-find and record of advice", "sub": "Filled from the conversation, gaps marked"}, {"icon": "message", "title": "Follow-up message", "sub": "A WhatsApp draft in the customer's language"}, {"icon": "users", "title": "CRM note and next meeting", "sub": "Tasks and an agenda, ready to use"}, {"icon": "file", "title": "Advisory report and proposal", "sub": "An internal briefing and a customer-friendly page"}], "impact": {"label": "BUSINESS IMPACT", "big": "Evenings back", "text": "Advisors review drafts instead of re-typing, and nothing is sent without them."}}, {"id": "s08", "kind": "feature", "beat": "b08", "kicker": "TALK TO JUNO", "title": "Ask <em>why</em>, and ask <em>what if</em>", "rows": [{"icon": "search", "title": "Why was a product picked?", "sub": "Answers from this customer's file and the documents"}, {"icon": "refresh", "title": "What if something changes?", "sub": "One more child: dependants 3 to 4, run again in seconds"}, {"icon": "calc", "title": "Sums done by code", "sub": "Exact figures with the working shown, never guessed"}, {"icon": "mic", "title": "Speak or type", "sub": "The discussion is saved with the suggestion"}], "impact": {"label": "BUSINESS IMPACT", "big": "Defend every suggestion", "text": "Advisors can explain the reasoning to the customer, and test changes live."}}, {"id": "s09", "kind": "feature", "beat": "b09", "kicker": "HEY JUNO", "title": "Hands-free across the <em>whole app</em>", "rows": [{"icon": "mic", "title": "Say \u201cHey Juno\u201d", "sub": "Open any screen or press any button by voice"}, {"icon": "play", "title": "Brief me, or read the report", "sub": "A 90-second briefing or the full report, read aloud"}, {"icon": "stop", "title": "Stop, pause, next", "sub": "Interrupt any reading in your own words"}, {"icon": "shield", "title": "Asks before it changes anything", "sub": "Saving, sending or removing needs a clear yes"}], "impact": {"label": "BUSINESS IMPACT", "big": "Use it anywhere", "text": "Between meetings or with busy hands, and a gain for accessibility."}}, {"id": "s10", "kind": "feature", "beat": "b10", "kicker": "DRESS REHEARSAL", "title": "Practise the meeting <em>before</em> it happens", "rows": [{"icon": "headphones", "title": "Juno briefs you", "sub": "In under a minute, on the customer and the goal"}, {"icon": "users", "title": "Juno plays the customer", "sub": "Built from your own debrief, spoken aloud"}, {"icon": "flag", "title": "Coach's notes", "sub": "What landed, what you missed, promises to reword"}, {"icon": "lock", "title": "Training only", "sub": "Nothing is saved or sent to the real customer"}], "impact": {"label": "BUSINESS IMPACT", "big": "Skill and confidence", "text": "Coaching at scale, without taking a manager's time."}}, {"id": "s11", "kind": "feature", "beat": "b11", "kicker": "BUILT FOR TRUST", "title": "Safe by design, <em>human</em> in control", "rows": [{"icon": "lock", "title": "Private by default", "sub": "ID and card numbers are never stored or shown"}, {"icon": "filter", "title": "Weak speech filtered out", "sub": "Noise and made-up words are discarded"}, {"icon": "check", "title": "Juno suggests, you decide", "sub": "No prices quoted, nothing sent, no auto-approval"}, {"icon": "globe", "title": "Mixed-language accuracy", "sub": "Words stay in the language they were spoken in"}], "impact": {"label": "BUSINESS IMPACT", "big": "Safe to scale", "text": "The control and audit trail that compliance and leaders expect."}}, {"id": "s12", "kind": "impact", "beat": "b12", "kicker": "WHAT IT MEANS FOR THE BUSINESS", "title": "Value for <em>everyone</em> in the chain", "tiles": [{"icon": "clock", "who": "Advisors", "text": "Time back to sell; review drafts, don't re-type"}, {"icon": "message", "who": "Customers", "text": "Faster follow-up in their own language"}, {"icon": "shield", "who": "Compliance", "text": "Risk caught in the moment, not weeks later"}, {"icon": "chart", "who": "Leadership", "text": "One view of volume, quality and needs"}]}, {"id": "s13", "kind": "stats", "beat": "b13", "kicker": "WHY NOW", "title": "The <em>opportunity</em> is on the table", "tiles": [{"v": "+36%", "text": "Adviser premiums are up (LIA 2025 and H1 2026 results)"}, {"v": "74%", "text": "of critical illness cover is still missing (protection gap)"}, {"v": "74,000", "text": "hours a month back: six hours per rep, an illustration to prove with AIA's own numbers"}]}, {"id": "s14", "kind": "close", "beat": "b14", "kicker": "LET'S PROVE IT TOGETHER", "title": "Just say, <em>\u201cHey Juno.\u201d</em>", "sub": "AIA Voice Insights \u00b7 a proof of concept for AIA Singapore"}]};
